import logging
import numpy as np
import pandas as pd

# ## common functions
def _remove_zeros(
    df,
    col,
    ):
    return (
        df
        .log.query(
            expr=f"`{col}` == {df.set_index(col).sum(axis=1).loc[lambda x: x>0].index.tolist()}",
        )
    )
    
def get_diff_ins(
    df_, ## 
    df0_vars, ## all data
    col_value, # exp
    col_sid,
    col_group,
    
    col_diffid=None, # if = col_id ('gene id') : do not sum
    
    exclude_zeros=True,
):
    """
    Notes:
        df_ example: values are aggregated
        
            gene id	ids	ids var2	sample id	comparison	mRNA expression (TPM)
            0	ENSG00000001626	ENST00000649406;ENST00000649781;ENST00000699605	ENST00000003084;ENST00000426809;ENST0000067378...	ACH-000007	ref	0.0
            ..
            1	ENSG00000001626	ENST00000649406;ENST00000649781;ENST00000699605	ENST00000003084;ENST00000426809;ENST0000067378...	ACH-000236	test	0.0

    """
    ## query filter 
    df0_vars=(
        df0_vars
        ## filter
        .log.query(
            expr=(
                f"`{col_sid}` == {df_[col_sid].tolist()}"
            )
        )
    )
    
    if col_diffid is None:
        df0_vars=(
            df0_vars
            ## agg by gene
            .groupby(
                [
                    col_sid,
                    col_group,
                ]
            )
                [col_value].sum()
                .reset_index()
            .log(col_sid)
            .log(col_group)
        )
        col_diffid=col_group
    else:
        # 
        assert col_diffid in df0_vars, df0_vars.columns.tolist()
        df_=(
            df_
                .assign(
                    **{
                        col_diffid: lambda df: df['ids']
                      }
                )
        )
        
    df0_vars=(
        df0_vars
        ## filter
        .log.query(
            expr=(
                f"`{col_diffid}` != {df_[col_diffid].tolist()}"    # wont apply to gene sets anyways        
            )
        )
    )

    ## values matrix
    df0_mat=(
        pd.concat(
            [
                df_.loc[:,[col_diffid,col_sid,col_value,]],
                df0_vars,
            ],
            axis=0,
        )
        .log(col_diffid)
        .pivot(
            index=col_diffid,
            columns=col_sid,
            values=col_value,
        )
        .astype(float)
        .reset_index()
        .rd.assert_no_dups([col_diffid])
    )

    ## samples matrix    
    df0_sids=(
        df_
        .loc[:,[col_sid,'comparison']]
        .rd.assert_dense()
        .astype('str')
    )

    if exclude_zeros:
        df0_mat=_remove_zeros(
            df0_mat,
            col_diffid,
        )
    return df0_mat,df0_sids

def get_ro(
    env_name=None,
    src_r_home=None,
    verbose=False,
    pkg_method='micromamba',
    ):
    if env_name is not None:
        from roux.lib.sys import run_com
        com_='which R'
        for pre in [
            f"{pkg_method} run -n {env_name}",
            '']:
            com=f"{pre} {com_}"
            try:       
                src_r_home=run_com(
                    com,
                    verbose=verbose,
                ).strip()
            except Exception: 
                logging.warning(f'src_r_home not found: {com}')
        if src_r_home is None:
            raise ValueError(src_r_home)
        # if verbose:
        #     logging.info(src_r_home)
        src_r_home=src_r_home.replace(
            '/bin/',
            # f'/envs/{env_name}/lib/',
            '/lib/',
        )    
        if verbose:
            logging.info(src_r_home)  
        if 'env_name' not in src_r_home:
            from pathlib import Path
            src_r_home=f'{Path.home()}/{pkg_method}/envs/{env_name}/lib/R'
            logging.warning(f"inferred: {src_r_home}")

    if src_r_home is not None:
        import os
        # Set R_HOME to the path of the desired R installation
        os.environ["R_HOME"] = src_r_home
    else:
        if verbose:
            from rpy2.robjects.packages import importr
            base = importr('base')
            logging.info(base.R_home())        
            
    # Now import rpy2
    import rpy2.robjects as ro   
    if verbose:
        logging.info(ro.r('version'))
    return ro

def get_diff(
    df0_exp,
    df0_sids,

    groups=['test','ref'],
    col_sample='sample id', # e.g. 'sample id' 
    col_condition='comparison', # e.g. 'comparison'
    col_gene='gene id', # e.g. 'gene id'
    
    # bkg='limma',
    robust=True,
    trend=True,
    counts=False, # False: TPMs, else counts
    
    plot=False,    
    verbose=False,   
    **kws_get_ro,
    ):
    ro=get_ro(
        verbose=verbose,
        **kws_get_ro,
    )
    """

    Notes:
        Limma can not be multi-processed.

        if (!require("BiocManager", quietly = TRUE))
            install.packages("BiocManager")
        BiocManager::install("edgeR")        
        
    """
    
    ## Pre-processing
    ### Transformations
    df0_mat=(
        df0_exp.set_index(col_gene)
        .astype(int if counts else float)
    )
    
    df1_sids=(
        df0_sids
        .rename(
            columns={
            col_sample:'sample',
            col_condition:'condition',
            },
        )
        .loc[:,['sample','condition']]
        .assign(
            ## test vs ref
            condition=lambda df: df['condition'].replace({groups[0]:'group2',groups[1]:'group1'})
        )
        # importatnt: align the order of samples
        .set_index('sample')
            .loc[df0_mat.columns.tolist(),:]
            .reset_index()
    )

    from rpy2.robjects import pandas2ri
    pandas2ri.activate()
    ro.globalenv['df0_mat'] = pandas2ri.py2rpy(df0_mat)
    ro.globalenv['df1_sids'] = pandas2ri.py2rpy(df1_sids)
    
    # from string import Template
    
    # robust=str(robust).upper()
    # trend=str(trend).upper()
    # verbose=str(verbose).upper()
    
    ro.globalenv['counts'] = ro.BoolVector([counts])
    
    ro.globalenv['robust'] = ro.BoolVector([robust])
    ro.globalenv['trend'] = ro.BoolVector([trend])
    
    ro.globalenv['verbose'] = ro.BoolVector([verbose])
    ro.globalenv['plot'] = ro.BoolVector([plot])
    
    com="""
if (!verbose) {
    invisible(capture.output({
      # your code here
    }, type = "message"))  # suppress stderr
}

# mLoad <- function(...) { sapply(sapply(match.call(), as.character)[-1], require, character.only = TRUE) }
# mLoad(
#     # tools, # pathlib
#     # glue, # fstring
#     # yaml, # io
#     # dplyr, reshape2, tibble, reticulate, # data
#     # ggplot2, ## plots
#     limma, 
# )
library(limma)

# print(df1_sids)
# print(levels(df1_sids$condition))
design <- model.matrix(~ 0 + df1_sids$condition)
colnames(design) <- unique(sort(df1_sids$condition))

if (verbose) {
    print("Design Matrix:")
    print(design)
}

# pre. values
# --- Step 1: Data Pre-processing based on input format ---
if (counts) {
    
    library(edgeR)
    
    # cat("Using counts-based limma-voom workflow (recommended).")
    
    # Create a DGEList object from the counts data
    # This is a key step for the limma-voom workflow
    dge <- edgeR::DGEList(counts = df0_mat)


    # 2. Filter out lowly expressed genes
    # This is the crucial step that fixes the error. It uses a sensible
    # default to keep genes with sufficient expression across samples.
    # The filterByExpr function will intelligently choose which genes to keep
    # based on your experimental design.
    keep <- filterByExpr(dge, design) # assuming 'design' is your design matrix
    dge <- dge[keep, , keep.lib.sizes=FALSE]

    # Perform TMM normalization to calculate normalization factors
    # This accounts for library size differences
    dge <- edgeR::calcNormFactors(dge)
    
    # Apply the voom transformation to convert counts to logCPM and compute precision weights.
    # This is the core step that makes count data suitable for limma's linear models.
    # Use the voom-transformed data and weights for the linear model fit
    df1_mat <- limma::voom(dge, design, plot = plot)

} else {
    # cat("Using a direct log-transformation for TPMs (not recommended).")
    # cat("This approach may produce unreliable results as it bypasses voom's variance modeling.")
    # Lines of code which are different from using counts.
    # We apply a manual log2 transformation, adding a small offset to avoid log(0).
    # This treats the data as continuous, similar to microarray data.
    # No voom() function is used here.
    df1_mat <- log2(df0_mat + 1)    
}


# fitting
fit <- lmFit(
    df1_mat,
    design
)

# Define contrast: comparing group2 vs group1
contrast <- makeContrasts(group2 - group1, levels = design)
fit2 <- contrasts.fit(fit, contrast)

if (verbose) {
    print(robust)
    print(trend)
}

fit2 <- eBayes(
    fit2,
    robust = robust,
    trend  = trend, ## lowers fc magnitude
    # proportion = 0.001, ## does not have effect on fc
)

# Extract the Results
results <- topTable(fit2, number = Inf, sort.by = "P")
"""
    ro.r(com)
    
    return (
        pandas2ri.rpy2py(ro.globalenv['results'])
        .rename_axis(df0_mat.index.name)
        .reset_index()
        )

def ttest(a,b):
    """
    Steps:
        1. Take p-log before calculating the p-values to adjust the distributions.
        2. Set the parameters for the test, so the function has only to parameters.
    """
    from scipy.stats import ttest_ind
    from roux.stat.transform import plog
    
    def pre_stats(
        a,
    ):
        return list(map(lambda x: plog(x,p=1,base=2),a))
    return ttest_ind(
        pre_stats(a),
        pre_stats(b),
        alternative='two-sided',
        random_state=0,
        permutations=None
    )

