from scipy.optimize import minimize_scalar
def get_diff_shrunk(
    counts: pd.DataFrame,
    # condition: pd.Series,
    cols_a,# test
    cols_b,# ref
    size_factors=True,
    tau_method="mle",
    errors="raise",
):
    """Empirical Bayes shrinkage of log2 fold changes (LFC).

    Shrinks raw LFC estimates toward zero using a gene-wise posterior mean.
    Genes with low counts or high variability (large SE) are shrunk more
    aggressively, reducing the influence of noise on the final LFC estimate.

    --------------------------------------------------------------------------
    Model
    --------------------------------------------------------------------------
    Prior:      LFC_true  ~ N(0, tau^2)
    Likelihood: LFC_obs   | LFC_true ~ N(LFC_true, se^2)
    Marginal:   LFC_obs   ~ N(0, tau^2 + se^2)

    Posterior mean (closed-form conjugate update):

        LFC_shrunk = [ tau^2 / (tau^2 + se^2) ] * LFC_obs
                     |________________________|
                      shrinkage_factor (0, 1)

    --------------------------------------------------------------------------
    tau (prior_scale)
    --------------------------------------------------------------------------
    tau is the standard deviation of the prior distribution on true LFCs.
    It controls the *global* aggressiveness of shrinkage across all genes:

        - Large tau  → prior is broad  → trust the data  → less shrinkage.
        - Small tau  → prior is narrow → trust the prior → more shrinkage.

    tau is shared across all genes; per-gene shrinkage degree is modulated
    by se (standard error), so low-count genes are always shrunk more than
    high-count genes for the same tau.

    How to choose a fixed tau (tau_method=<float>):
        - Estimate tau once on a reference/pilot dataset using tau_method="mle",
          then hard-code the returned prior_scale value for downstream runs.
        - Alternatively, use the median absolute raw LFC of your reference as
          a rough proxy (equivalent to tau_method="median").
        - Typical range for bulk RNA-seq: 0.5–2.0. Values outside this range
          should be validated against known positive controls.
        - For cross-dataset comparisons, fix tau to the same value across all
          datasets to ensure shrunk LFCs are on a comparable scale.

    --------------------------------------------------------------------------
    Args
    --------------------------------------------------------------------------
    counts:
        Raw count matrix (genes x samples). Non-negative integers.
    condition:
        Binary indicator (0/1). LFC is computed as condition 1 vs 0.
    size_factors:
        If True, apply median-of-ratios normalization (DESeq2-style) before
        computing LFC and SE. If False, shrinkage is applied directly on raw
        counts. Disabling removes cross-sample library-size correction but
        the shrinkage logic (low-count moderation) remains intact.
    tau_method:
        Controls how the prior scale tau is determined.
            "mle"   : Estimate tau by maximizing marginal likelihood
                      log p(LFC_obs | tau). Data-adaptive, default.
            "median": Set tau = median(|LFC_raw|). Fast heuristic, robust
                      to LFC outliers.
            <float> : Use a user-supplied constant. Enables cross-dataset
                      comparability. See docstring above for guidance on
                      choosing a value.
    errors:
        'raise' to raise on input issues, else logs warning.

    Returns:
        dict with keys:
            lfc_raw:      Raw log2 fold changes.
            lfc_shrunk:   Shrunk log2 fold changes.
            se_raw:       Standard errors of raw LFCs.
            prior_scale:  tau used for shrinkage (float).
            mean:         Per-gene log geometric means (used for QC plots).
    """

    # --- QC ---
    # assert (len(set(condition))==2), "condition must be binary"
    assert counts.shape[1] == len(cols_a+cols_b), "counts columns must match condition length"
    assert (counts.values >= 0).all(), "counts must be non-negative"
    assert tau_method in ("mle", "median") or isinstance(
        tau_method, (int, float)
    ), "tau_method must be 'mle', 'median', or a float"

    # --- size factors (median-of-ratios, DESeq2 style) ---
    with np.errstate(divide="ignore"):
        log_counts = np.log(counts.values.astype(float))
    log_counts[~np.isfinite(log_counts)] = np.nan
    geo_means = np.nanmean(log_counts, axis=1)  # per-gene log geometric mean

    if size_factors:
        valid = np.isfinite(geo_means)
        sf = np.exp(
            np.nanmedian(log_counts[valid] - geo_means[valid, None], axis=0)
        )  # per-sample
    else:
        sf = np.ones(counts.shape[1])  # g: identity, no normalization

    # --- normalized counts ---
    normed = counts.values.astype(float) / sf[None, :]

    # --- raw LFC and SE via Wald-style estimation ---
    pseudocount = 1.0  # g: required; log(0) breaks LFC and SE
    idx1 = counts.columns.isin(cols_a)
    idx0 = counts.columns.isin(cols_b)

    mean1 = (normed[:, idx1] + pseudocount).mean(axis=1)
    mean0 = (normed[:, idx0] + pseudocount).mean(axis=1)
    lfc_raw = np.log2(mean1) - np.log2(mean0)

    # g: SE via delta method: Var(log(X)) ≈ Var(X) / mean(X)^2
    var1 = np.var(normed[:, idx1], axis=1, ddof=1) + pseudocount
    var0 = np.var(normed[:, idx0], axis=1, ddof=1) + pseudocount
    n1, n0 = idx1.sum(), idx0.sum()
    se_raw = np.sqrt(
        (var1 / (n1 * mean1**2) + var0 / (n0 * mean0**2)) / np.log(2) ** 2
    )
    se_raw = np.clip(se_raw, 1e-8, None)  # numerical floor

    # --- estimate or set tau ---
    if tau_method == "mle":
        # g: maximize log p(LFC_obs | tau); marginal: LFC_obs ~ N(0, tau^2 + se^2)
        def neg_log_marginal(log_tau):
            tau2 = np.exp(log_tau * 2)
            total_var = tau2 + se_raw**2
            return 0.5 * np.sum(np.log(total_var) + lfc_raw**2 / total_var)

        res = minimize_scalar(neg_log_marginal, bounds=(-6, 6), method="bounded")
        prior_scale = np.exp(res.x)

    elif tau_method == "median":
        prior_scale = float(np.median(np.abs(lfc_raw)))

    else:  # g: user-supplied float
        prior_scale = float(tau_method)

    # --- posterior mean (shrunk LFC) ---
    # LFC_shrunk = (tau^2 / (tau^2 + se^2)) * LFC_obs
    tau2 = prior_scale**2
    shrinkage_factor = tau2 / (tau2 + se_raw**2)  # per-gene, in (0, 1)
    lfc_shrunk = shrinkage_factor * lfc_raw

    return {
        "lfc_raw": pd.Series(lfc_raw, index=counts.index),
        "lfc_shrunk": pd.Series(lfc_shrunk, index=counts.index),
        "se_raw": pd.Series(se_raw, index=counts.index),
        "prior_scale": prior_scale,
        "mean": geo_means,
    }
